mapper.select:
/** [PCM] commonSql - selectEstiCodeList - 공통코드 조회 > 평가코드 일반 */ SELECT VESTICODE as "vEstiCode" /* 01_평가코드 */ , VESTICODENAME as "vEstiCodeName" /* 02_설명 */ , VESTICODEVIEW as "vEstiCodeView" /* 03_평가코드 View */ , VESTICODEUPDATE as "vEstiCodeUpdate" /* 04_평가코드 갱신 */ FROM TCA4001
AND VESTICODEVIEW = 'Y'
ORDER BY VESTICODE DESC

/** [PCM] commonSql - selectProjectCodeList - 공통코드 조회 > 과제코드 */ SELECT B.VESTICODE as "vEstiCode" /* 01_평가코드 */ , B.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , B.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , B.VDEPTNAME as "vDeptName" /* 04_센터명 */ , B.VGOVNAME as "vGovName" /* 05_부처명 */ , B.VPROJECTDIVISION as "vProjectDivision" /* 06_사업명 */ , B.VTOTSTARTDATE as "vTotStartDate" /* 07_총과제시작일 */ , B.VTOTENDDATE as "vTotEndDate" /* 08_총과제종료일 */ , B.VSTARTDATE as "vStartDate" /* 09_과제시작일 */ , B.VENDDATE as "vEndDate" /* 10_과제종료일 */ , B.VPROJECTPM as "vProjectPm" /* 11_과제 PM */ , ( SELECT A.VNAME FROM TCA4002 A WHERE A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VPROJECTPM ) as "vProjectPmName" /* 12_과제 PM명 */ , B.VPROJECTEVA as "vProjectEva" /* 13_과제 평가자 */ , ( SELECT A.VNAME FROM TCA4002 A WHERE A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VPROJECTEVA ) as "vProjectEvaName" /* 14_과제 평가자명 */ , B.VPROJECTGOAL as "vProjectGoal" /* 15_과제 목표 */ , B.VPROJECTMILESTONE as "vProjectMilestone" /* 16_평가 기간내 Milestone */ , B.VESTISTEP as "vEstiStep" /* 17_과제 진행단계 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VCONFIRM, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vConfirm" /* 18_확인여부 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VFINISH, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vFinish" /* 19_완료여부 */ FROM TCA4003 B
B.VESTICODE = #{vEstiCode}
AND B.VPROJECTCODE = #{vProjectCode}
AND B.VPROJECTPM = #{vProjectPm}
AND B.VPROJECTEVA = #{vProjectEva}
ORDER BY B.VPROJECTCODE

/** [PCM] commonSql - selectHrInfo - 인사정보 조회 > 사원 */ SELECT A.VEMPLNO as "vEmplNo" , A.VNAME as "vName" , A.VDEPTCODE as "vDeptCode" , B.VTEAMNAME as "vDeptName" , A.VTEAMCODE as "vTeamCode" , C.VTEAMNAME as "vTeamName" , A.VPOSCODE as "vPosCode" , D.VPOSNAME as "vPosName" , A.VDUTYCODE as "vDutyCode" , A.VGRADECODE as "vGradeCode" , D.VGRADENAME as "vGradeName" , E.VRESINO as "vResiNo" , E.VRESIDENCEADDR as "vResidenceAddr" , E.VBIRTH as "dBirth" , A.VENTER as "dEnter" , A.VRETIRE as "dRetire" , A.VJOBCLASS as "vJobClass"
, NVL( ( SELECT CASE WHEN P.VESTIYN = 'Y' THEN CASE WHEN Q.VESTICODEUPDATE = 'N' THEN DECODE(P.VGRADE, 'A', P.VGRADE, 'E') ELSE NVL(P.VGRADE, 'X') END ELSE DECODE(P.VGRADE, 'A', P.VGRADE, 'X') END FROM TCA4002 P, ( SELECT VESTICODE, VESTICODEUPDATE FROM TCA4001
ROWNUM = '1'
ORDER BY VESTICODE DESC ) Q
P.VESTICODE = Q.VESTICODE AND P.VEMPLNO = #{vEmplNo}
), 'X') as "vMenuGrade"
FROM TAA2101 A, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG IN ('1', '2')) B, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG = '3' ORDER BY VHIGHTEAM, VTEAMCODE) C, (SELECT VPOSCODE, VPOSNAME, VGRADENAME FROM TAZ2003) D, TAA2102 E
AND A.VDEPTCODE = B.VTEAMCODE(+) AND A.VTEAMCODE = C.VTEAMCODE(+) AND A.VPOSCODE = D.VPOSCODE(+) AND A.VEMPLNO = E.VEMPLNO(+)
AND A.VNAME LIKE '%'|| #{vName} ||'%'
AND A.VEMPLNO = #{vEmplNo}
AND A.VEMPLNO LIKE '%'|| #{vEmplNo} || '%'
/** AND (A.VRETIREYN != 'Y' OR A.VRETIREYN IS NULL) */ AND A.VRETIRE IS NULL
ORDER BY A.VDEPTCODE, A.VTEAMCODE, A.VPOSCODE, A.NESTIPOINT DESC

/** [PCM] commonSql - selectProject - 과제코드 조회 */ SELECT B.VPROJECTCODE as "vProjectCode" , A.VKEYPROJECTNAME as "vKeyProjectName" , A.VKEYPROJECTCODE as "vKeyProjectCode" , C.VTEAMNAME as "vDeptName" , A.VPROORGNAME as "vGovName" , A.VPROJECTDIVISION as "vProjectDivision" , A.VSTARTDATE as "vTotStartDate" , A.VENDDATE as "vTotEndDate" , B.VSTARTDATE as "vStartDate" , B.VENDDATE as "vEndDate" , A.VMANAGER as "vProjectPm" , D.VNAME as "vProjectPmName" , A.VGOAL as "vProjectGoal" FROM TCZ2003 A, TCZ2006 B, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VUSEYN = 'Y' AND VTEAMFLAG IN ('1', '2')) C, TAA2101 D
AND A.VKEYPROJECTCODE = B.VKEYPROJECTCODE AND B.VPROJECTSTEP = '3' AND A.VDEPTCODE = C.VTEAMCODE(+) AND A.VMANAGER = D.VEMPLNO
ORDER BY B.VPROJECTCODE
